#!/bin/sh
set -eu

: "${TELEMEDICINE_TURN_SECRET:?TURN signing secret is missing}"
: "${TELEMEDICINE_LAN_IP:?LAN IP is missing}"
: "${TELEMEDICINE_PUBLIC_IP:?Public IP is missing}"

PORT="${TELEMEDICINE_TURN_PORT:-3478}"
MIN_PORT="${TELEMEDICINE_RELAY_MIN_PORT:-49160}"
MAX_PORT="${TELEMEDICINE_RELAY_MAX_PORT:-49259}"

# Only for LAN testing with WSL mirrored networking. The forwarded external
# address must actually be reachable on the PC from other LAN devices.
# TURN REST credentials are generated by the existing signaling application.
# Coturn 4.18.0 removed --no-cli and --no-dtls (both disabled by default).
exec turnserver \
  --listening-ip=0.0.0.0 \
  --listening-port="$PORT" \
  --relay-ip="$TELEMEDICINE_LAN_IP" \
  --external-ip="$TELEMEDICINE_PUBLIC_IP/$TELEMEDICINE_LAN_IP" \
  --realm=norhnaim.local \
  --fingerprint \
  --use-auth-secret \
  --static-auth-secret="$TELEMEDICINE_TURN_SECRET" \
  --min-port="$MIN_PORT" \
  --max-port="$MAX_PORT" \
  --no-tls
